class Solution {
public:
    int minOperations(vector<int>& nums) {
        int increments = 0;
        int maxBits = 0;
        for (int x : nums) {
            increments += __builtin_popcount((unsigned)x);
            if (x > 0) {
                int bits = 32 - __builtin_clz((unsigned)x);
                if (bits > maxBits) maxBits = bits;
            }
        }
        return increments + (maxBits > 0 ? maxBits - 1 : 0);
    }
};
